    /* Coming Soon Countdown */
const targetDate = new Date("2026-12-31T00:00:00");

function updateCountdown() {
  const now = new Date();
  const diff = targetDate - now;

  if (diff <= 0) {
    document.getElementById("days").textContent    = "00";
    document.getElementById("hours").textContent   = "00";
    document.getElementById("minutes").textContent = "00";
    document.getElementById("seconds").textContent = "00";
    return;
  }

  const days    = Math.floor(diff / (1000 * 60 * 60 * 24));
  const hours   = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
  const seconds = Math.floor((diff % (1000 * 60)) / 1000);

  document.getElementById("days").textContent    = String(days).padStart(2, "0");
  document.getElementById("hours").textContent   = String(hours).padStart(2, "0");
  document.getElementById("minutes").textContent = String(minutes).padStart(2, "0");
  document.getElementById("seconds").textContent = String(seconds).padStart(2, "0");
}

setInterval(updateCountdown, 1000);
updateCountdown();

/* Video play overlay */
const videoPlayOverlay = document.getElementById("videoPlayOverlay");
const videoPlayBtn     = document.getElementById("videoPlayBtn");
const videoEl          = document.querySelector(".video-player");

if (videoPlayBtn && videoEl) {
  videoPlayOverlay.addEventListener("click", function () {
    videoEl.play();
    videoPlayOverlay.classList.add("hidden");
  });

  videoEl.addEventListener("pause", function () {
    videoPlayOverlay.classList.remove("hidden");
  });
}



// ----------
document.addEventListener('DOMContentLoaded', function () {

    (function () {

        // ==============================
        // CART STORAGE
        // ==============================

        var STORAGE_KEY = 'ridge_cart_items';
        var ORDERS_KEY = 'ridge_orders_count';

        var cart = JSON.parse(
            localStorage.getItem(STORAGE_KEY) || '[]'
        );

        var ordersCount = parseInt(
            localStorage.getItem(ORDERS_KEY) || '0',
            10
        );


        // ==============================
        // HTML ELEMENTS
        // ==============================

        var overlay = document.getElementById('cartOverlay');
        var sidebar = document.getElementById('cartSidebar');
        var body = document.getElementById('cartSidebarBody');

        var pillCount = document.getElementById('cartPillCount');
        var ordersNote = document.getElementById('cartOrdersNote');
        var totalAmount = document.getElementById('cartTotalAmount');

        var checkoutBtn = document.getElementById('cartCheckoutBtn');
        var navCartBtn = document.getElementById('navCartBtn');
        var closeBtn = document.getElementById('cartCloseBtn');

        var cartFab = document.getElementById('cartFab');
        var cartFabCount = document.getElementById('cartFabCount');


        // ==============================
        // CHECK ELEMENTS
        // ==============================

        if (!overlay ||
            !sidebar ||
            !body ||
            !pillCount ||
            !ordersNote ||
            !totalAmount ||
            !checkoutBtn) {

            console.error(
                'Cart Error: Required cart HTML elements are missing.'
            );

            return;
        }


        // ==============================
        // PRICE
        // ==============================

        function parsePrice(price) {

            return parseFloat(
                String(price).replace(/[^0-9.]/g, '')
            ) || 0;

        }


        // ==============================
        // SAVE CART
        // ==============================

        function save() {

            localStorage.setItem(
                STORAGE_KEY,
                JSON.stringify(cart)
            );

            localStorage.setItem(
                ORDERS_KEY,
                String(ordersCount)
            );

        }


        // ==============================
        // CART COUNT
        // ==============================

        function badgeCount() {

            return cart.reduce(function (sum, item) {

                return sum + Number(item.qty || 0);

            }, 0);

        }


        // ==============================
        // UPDATE BADGES
        // ==============================

        function updateBadges() {

            var count = badgeCount();

            pillCount.textContent = count;

            if (cartFabCount) {
                cartFabCount.textContent = count;
            }

            ordersNote.textContent =
                ordersCount +
                (ordersCount === 1
                    ? ' order checked out so far'
                    : ' orders checked out so far');

        }


        // ==============================
        // RENDER CART
        // ==============================

        function render() {

            updateBadges();


            // EMPTY CART
            if (!cart.length) {

                body.innerHTML = `
                    <div class="cart-empty">
                        <i class="ri-shopping-cart-line"></i>

                        <p>
                            Your cart is empty.
                        </p>

                        <span>
                            Add an edition or some merchandise
                            to get started.
                        </span>
                    </div>
                `;

                totalAmount.textContent = '$0.00';

                checkoutBtn.disabled = true;

                return;
            }


            checkoutBtn.disabled = false;


            var html = '';
            var total = 0;


            cart.forEach(function (item, index) {

                var quantity = Number(item.qty) || 1;

                var price = parsePrice(item.price);

                var lineTotal = price * quantity;

                total += lineTotal;


                html += `

                    <div class="cart-item-row">

                        <img
                            class="cart-item-thumb"
                            src="${item.image || 'images/book-update-1.png'}"
                            alt="${item.name}"
                        >


                        <div class="cart-item-info">

                            <h6>
                                ${item.name}
                            </h6>


                            <span class="cart-item-price">
                                ${item.price}
                            </span>


                            <div class="cart-item-qty">

                                <button
                                    type="button"
                                    data-action="dec"
                                    data-idx="${index}">
                                    −
                                </button>


                                <span>
                                    ${quantity}
                                </span>


                                <button
                                    type="button"
                                    data-action="inc"
                                    data-idx="${index}">
                                    +
                                </button>

                            </div>

                        </div>


                        <button
                            type="button"
                            class="cart-item-remove"
                            data-action="remove"
                            data-idx="${index}">

                            <i class="ri-delete-bin-line"></i>

                        </button>

                    </div>

                `;

            });


            body.innerHTML = html;

            totalAmount.textContent =
                '$' + total.toFixed(2);

        }


        // ==============================
        // OPEN CART
        // ==============================

        function openCart() {

            overlay.classList.add('active');

            sidebar.classList.add('active');

            document.body.classList.add('cart-open');

            render();

        }


        // ==============================
        // CLOSE CART
        // ==============================

        function closeCart() {

            overlay.classList.remove('active');

            sidebar.classList.remove('active');

            document.body.classList.remove('cart-open');

        }


        // ==============================
        // ADD TO CART
        // ==============================

        window.addToCart = function (name, price, image) {

            var existing = cart.find(function (item) {

                return item.name === name;

            });


            if (existing) {

                existing.qty += 1;

            } else {

                cart.push({

                    name: name,

                    price: price,

                    image: image || '',

                    qty: 1

                });

            }


            save();

            render();


            // Open cart automatically
            openCart();

        };


        // ==============================
        // CART ITEM BUTTONS
        // ==============================

        body.addEventListener('click', function (event) {

            var button =
                event.target.closest(
                    'button[data-action]'
                );


            if (!button) {
                return;
            }


            var index =
                parseInt(
                    button.getAttribute('data-idx'),
                    10
                );


            var action =
                button.getAttribute('data-action');


            if (!cart[index]) {
                return;
            }


            // PLUS
            if (action === 'inc') {

                cart[index].qty += 1;

            }


            // MINUS
            if (action === 'dec') {

                cart[index].qty -= 1;


                if (cart[index].qty <= 0) {

                    cart.splice(index, 1);

                }

            }


            // REMOVE
            if (action === 'remove') {

                cart.splice(index, 1);

            }


            save();

            render();

        });


        // ==============================
        // CHECKOUT
        // ==============================

        checkoutBtn.addEventListener(
            'click',
            function () {

                if (!cart.length) {
                    return;
                }


                ordersCount += 1;


                cart = [];


                save();


                body.innerHTML = `

                    <div class="cart-confirm">

                        <i class="ri-checkbox-circle-line"></i>

                        <h5>
                            Order placed!
                        </h5>

                        <p>
                            Thanks for your order.
                            You now have
                            ${ordersCount}
                            ${ordersCount === 1
                                ? 'order'
                                : 'orders'}
                            checked out.
                        </p>

                    </div>

                `;


                totalAmount.textContent =
                    '$0.00';


                checkoutBtn.disabled = true;


                pillCount.textContent = '0';


                if (cartFabCount) {

                    cartFabCount.textContent = '0';

                }


                ordersNote.textContent =
                    ordersCount +
                    (ordersCount === 1
                        ? ' order checked out so far'
                        : ' orders checked out so far');

            }
        );


        // ==============================
        // NAV CART BUTTON
        // ==============================

        if (navCartBtn) {

            navCartBtn.addEventListener(
                'click',
                function (event) {

                    event.preventDefault();

                    openCart();

                }
            );

        }


        // ==============================
        // CLOSE BUTTON
        // ==============================

        if (closeBtn) {

            closeBtn.addEventListener(
                'click',
                closeCart
            );

        }


        // ==============================
        // OVERLAY CLICK
        // ==============================

        overlay.addEventListener(
            'click',
            closeCart
        );


        // ==============================
        // FLOATING CART BUTTON
        // ==============================

        if (cartFab) {

            cartFab.addEventListener(
                'click',
                openCart
            );

        }


        // ==============================
        // ESC KEY
        // ==============================

        document.addEventListener(
            'keydown',
            function (event) {

                if (event.key === 'Escape') {

                    closeCart();

                }

            }
        );


        // ==============================
        // INITIAL LOAD
        // ==============================

        render();


        console.log(
            'Ridge merchandise cart loaded successfully.'
        );

    })();

});



